INSERT INTO public.lesson_content (lesson_key, course_id, title, content_html, updated_at)
VALUES
  ('kurmanji-course-2-lesson-07.html','kurmanji-course-2','جێناوە کەسییەکان و حاڵەتی ڕاستەوخۆ و ناڕاستەوخۆ','<section class="klesson-card"><h2>١. فۆڕمەکانی جێناوی کەسی</h2><p>لە کورمانجیی ستاندارددا فۆڕمە ڕاستەوخۆکان بریتین لە ez, tu, ew, em, hûn, ew؛ فۆڕمە ناڕاستەوخۆکانیش min, te, wî/wê, me, we, wan. ئەم دوو کۆمەڵەیە لە Haig و Öpengin (2018)دا بە شێوەی خشتە هاتوون.</p></section><section class="klesson-card"><h2>٢. حاڵەت و ئەرکی ڕستە</h2><p>حاڵەتی ناڕاستەوخۆ لە کورمانجی‌دا لە چەند ژینگەی ڕێزمانی دەردەکەوێت؛ بۆیە نابێت بە یاسای «هەمیشە بکەر ناڕاستەوخۆیە» یان «هەمیشە بەرکار ڕاستەوخۆیە» کورت بکرێتەوە. کات، جۆری کردار و پێکهاتەی ڕستە کاریگەرییان هەیە.</p></section><section class="klesson-card"><h2>٣. سیستەمی ڕابردوو</h2><p>لە ڕستەی ڕابردووی زۆرێک لە کردارە تێپەڕەکاندا، بکەر دەتوانێت بە فۆڕمی ناڕاستەوخۆ دەربکەوێت، لە کاتێکدا بەرکار بە شێوەیەکی دیکە ڕێکدەکەوێت. ئەمە بابەتی گرنگی سیستەمی حاڵەت و ergativity ـە و پەیویستی بە شیکردنەوەی ڕستەی تەواو هەیە.</p></section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note">خشتەی جێناوەکان لە Haig و Öpengin (2018) و Thackston هەڵبژێردراوە. لە پشکنینی ڕستەی تایبەتدا کات و جۆری کردار دیاری بکە.</p></section>
<section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>فۆڕمە ڕاستەوخۆ و ناڕاستەوخۆکانی ez، tu، ew چین؟</li><li>بۆچی حاڵەت تەنیا بە ئەرکی بکەر/بەرکار ناسراو ناکرێت؟</li><li>ڕابردووی کردارە تێپەڕەکان چ پەیوەندییەکیان بە حاڵەتی ناڕاستەوخۆوە هەیە؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. Berlin: De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI: 10.1515/9783110421682-004</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">وەشانی سەرچاوە</a>.</li></ul><p class="klesson-note">نمونە و یاساکان لە چوارچێوەی کورمانجیی ستاندارددا پێشکەش کراون؛ بۆ جیاوازیی شێوەزار و فۆڕمی تایبەت، دەبێت سەرچاوە و سیاق دیاری بکرێن.</p></section>',now()),
  ('kurmanji-course-2-lesson-08.html','kurmanji-course-2','کردار، ڕەگ، کەس و ژمارە','<section class="klesson-card"><h2>١. ڕەگی کردار</h2><p>بۆ شیکردنەوەی کردار، فۆڕمی بنەڕەتی و ڕەگی کردار بناسە؛ دواتر دیاری بکە چ نیشانەیەک کەس، ژمارە، کات یان ڕەوش دەردەخات. هەمو کردارەکان بە هەمان ڕێسا فۆڕم وەرناگرن.</p></section><section class="klesson-card"><h2>٢. کەس و ژمارە</h2><p>فۆڕمی کردار لە ڕستەدا لەگەڵ کەس و ژمارە پەیوەندی هەیە، بەڵام شێوازی ئەم پەیوەندییە بە کات و جۆری ڕستە دەگۆڕێت. جێناوی ئاشکرا هەمو جارێک بە مانای ئەوە نیە کە نیشانەی کەس لە کرداردا نیە.</p></section><section class="klesson-card"><h2>٣. تێپەڕی و ناتێپەڕی</h2><p>کرداری ناتێپەڕ زۆرجار بێ بەرکاری ڕاستەوخۆ بەکاردێت؛ کرداری تێپەڕ دەتوانێت بەرکاری ڕاستەوخۆ وەربگرێت. ئەم جیاوازییە گرنگە بۆ تێگەیشتن لە حاڵەت و ڕێککەوتن، بە تایبەتی لە ڕستە ڕابردووەکاندا.</p></section><section class="klesson-card"><h2>٤. بەراوردی فۆڕمەکان</h2><p>لە خشتەی کردارەکانی Haig (2018)، نموونەی کاتی ئێستا بۆ کرداری تێپەڕ <em>ez dibêjim</em> «من دەڵێم»، نموونەی ڕابردووی کرداری ناتێپەڕ <em>ez hatim</em> «من هاتم»، و نموونەی ڕابردووی کرداری تێپەڕ <em>min xwar</em> «من خوارد» هاتوون. ئەم بەراوردە نیشان دەدات کە لە کورمانجی‌دا فۆڕمی جێناو و ڕێککەوتنی کردار بە کات و تێپەڕی/ناتێپەڕی پەیوەستە؛ نابێت یاسای یەکسان بۆ هەموو ئەم پێکهاتانە دابنرێت.</p><p class="klesson-note">سەرچاوە: Haig (2018)، Table 14، نموونەی conjugationی کردارەکان.</p></section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note">ئەم وانەیە چوارچێوەی شیکردنەوە دەدات؛ بۆ خشتەی تەواوی فۆڕمەکانی کردار، سەرچاوەی ڕێزمانی بە پێی کردار و کات بخوێنەوە و فۆڕمی تایبەت بە گشتی مەکە.</p></section>
<section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>لە شیکردنەوەی کرداردا چ زانیارییەکان دەبێت دیاری بکرێن؟</li><li>جیاوازی کردارە تێپەڕ و ناتێپەڕەکان چیە؟</li><li>بۆچی فۆڕمی کردار بە کات و جۆری ڕستەوە پەیوەستە؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. Berlin: De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI: 10.1515/9783110421682-004</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">وەشانی سەرچاوە</a>.</li></ul><p class="klesson-note">نمونە و یاساکان لە چوارچێوەی کورمانجیی ستاندارددا پێشکەش کراون؛ بۆ جیاوازیی شێوەزار و فۆڕمی تایبەت، دەبێت سەرچاوە و سیاق دیاری بکرێن.</p></section>',now()),
  ('kurmanji-course-2-lesson-09.html','kurmanji-course-2','کاتی ئێستا، ڕابردوو و داهاتوو','<section class="klesson-card"><h2>١. کاتی ئێستا</h2><p>لە کاتی ئێستادا، پێشگر و فۆڕمی کردار دەتوانن زانیاریی کات و ڕەوش بگەیەنن. بۆ نمونە، فۆڕمەکانی di- لە زۆر کردارەکاندا لە پێکهاتەی ئێستادا دەردەکەون؛ بەڵام کردارە تایبەتەکان فۆڕمی جیاوازیان هەیە.</p></section><section class="klesson-card"><h2>٢. کاتی ڕابردوو</h2><p>ڕابردوو یەک شێوەی سادە نیە: جیاوازی نێوان کردارە تێپەڕ و ناتێپەڕەکان و فۆڕمەکانی کردار لە ڕێکخستنی ڕستەدا کاریگەری هەیە. لە ڕستەی ڕابردووی کردارە تێپەڕەکاندا سیستەمی حاڵەت گرنگە.</p></section><section class="klesson-card"><h2>٣. داهاتوو و واتای کات</h2><p>واتای داهاتوو دەتوانێت بە پێکهاتەی کردار و وشەی یاریدەدەر دەرببڕدرێت؛ شێوەی بەکارهێنان بە سیاق و جۆری ڕستەوە پەیوەستە. لە شیکردنەوەدا فۆڕمی کردار لەگەڵ نیشانەکانی کات و سیاق بە یەکەوە بخوێنەوە.</p></section>
<section class="klesson-card"><h2>٤. بەراوردی فۆڕمەکانی کردار</h2><p>لە نمونەکانی Haig (2018)، خشتەی ١٤، <code>ez dibêjim</code> فۆڕمی ئێستایە؛ <code>ez hatim</code> ڕابردووی کرداری ناتێپەڕە؛ <code>min xwar</code> ڕابردووی کرداری تێپەڕە. لە ڕستەی ڕابردووی تێپەڕدا، فۆڕمی جێناو و ڕێککەوتنی کردار لەگەڵ ئەوەی لە ڕستەی ئێستادا دەبینرێت جیاوازە.</p><p>بۆ جیاکردنەوەی ڕابردووی سادە لە ڕابردووی بەردەوام/ناکامڵ، سەرچاوە ئەم بەراوردەش دەدات: <code>ez hatim</code> (ڕابردووی سادەی ناتێپەڕ) لە بەرامبەر <code>ez dihatim</code> (ڕابردووی بەردەوامی ناتێپەڕ)، هەروەها <code>min xwar</code> لە بەرامبەر <code>min dixwar</code>.</p><p>بۆ داهاتوو، Haig (§2.6.4) نمونەی <code>ew dē mesel-ē ji te re bēž-e</code> دەهێنێتەوە: «ئەو کێشەکە بۆ تۆ دەڵێت». لەو نمونەیەدا <code>dē</code> نیشانەی داهاتووە و کردارەکە فۆڕمی subjunctive ـە. ئەم نووسینەی لاتینییە بە شێوەی سەرچاوە پارێزراوە؛ فۆڕمی نوێی دروستکراو نیە.</p></section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note">ئەم وانەیە پێشەکییە بۆ سیستەمی کات و ڕەوش. خشتەی پارادایمی تەواو پەیویستی بە سەرچاوەی تایبەت و دیاریکردنی شێوەزار هەیە؛ لێرەدا فۆڕمی ناپشکنراو دروست نەکراوە. خشتەی پارادایمی تەواو پەیویستی بە سەرچاوەی تایبەت و دیاریکردنی شێوەزار هەیە؛ لێرەدا فۆڕمی ناپشکنراو دروست نەکراوە.</p></section>
<section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>پێشگری di- لە زۆر کردارەکانی کاتی ئێستادا چ ڕۆڵێکی هەیە؟</li><li>بۆچی ڕابردووی کردارە تێپەڕەکان بە جیاوازی لە کردارە ناتێپەڕەکان دەخوێندرێتەوە؟</li><li>داهاتوو بۆچی نابێت بە یاسای پاشگری یەکسان کورت بکرێتەوە؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. Berlin: De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI: 10.1515/9783110421682-004</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">وەشانی سەرچاوە</a>.</li></ul><p class="klesson-note">نمونە و یاساکان لە چوارچێوەی کورمانجیی ستاندارددا پێشکەش کراون؛ بۆ جیاوازیی شێوەزار و فۆڕمی تایبەت، دەبێت سەرچاوە و سیاق دیاری بکرێن.</p></section>',now()),
  ('kurmanji-course-2-lesson-10.html','kurmanji-course-2','ڕستەی نەفی و پرسیاری','<section class="klesson-card"><h2>١. نەفیی کردار</h2><p>لە زۆر فۆڕمەکانی کاتی ئێستای کورمانجی‌دا، na- بۆ نەفی بەکاردێت و لە بەرابەر di- دێت؛ بەڵام کردارە تایبەتەکان هەن، بۆیە یاساکە نابێت بەبێ پشکنین بۆ هەمو کردارەکان بگشتێندرێت.</p></section><section class="klesson-card"><h2>٢. نەفیی ڕستەی ناوەکی</h2><p>نەفیی ڕستەی ناوەکی و نەفیی کردار هەمیشە بە هەمان فۆڕم دروست نابن. فۆڕمی نەفی دەبێت بە پێی جۆری پێکهاتە و کردار بپشکنرێت.</p></section><section class="klesson-card"><h2>٣. پرسیاری بەڵێ/نەخێر و وشە پرسیاری</h2><p>پرسیاری بەڵێ/نەخێر دەتوانێت بە ئاواز و سیاق ناسرێتەوە؛ پرسیاری زانیاریییش وشەی پرسیاری وەک کێ، چی، لە کوێ یان کەی بەکار دەهێنێت. ڕیزبەندی وشەکان لە ڕستەی پرسیاریدا دەبێت بە پێی شێوەی ستاندارد و سیاق بپشکنرێت.</p></section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note">فۆڕمەکانی نەفی و پرسیار لە کردارە جیاوازەکاندا بەراورد بکە؛ یاسایەکی گشتی لە نمونەی تاکەوە مەدەرهێنە.</p></section>
<section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>na- لە زۆر فۆڕمەکانی کاتی ئێستادا چی دەکات؟</li><li>جیاوازی نەفیی کردار و ڕستەی ناوەکی چیە؟</li><li>دوو جۆری پرسیاری سەرەکی چین؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. Berlin: De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI: 10.1515/9783110421682-004</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">وەشانی سەرچاوە</a>.</li></ul><p class="klesson-note">نمونە و یاساکان لە چوارچێوەی کورمانجیی ستاندارددا پێشکەش کراون؛ بۆ جیاوازیی شێوەزار و فۆڕمی تایبەت، دەبێت سەرچاوە و سیاق دیاری بکرێن.</p></section>',now()),
  ('kurmanji-course-2-lesson-11.html','kurmanji-course-2','ڕێکخستنی وشەکان و پێکهاتەی ڕستە','<section class="klesson-card"><h2>١. ڕستەی سادە</h2><p>بۆ شیکردنەوەی ڕستە، بکەر، کردار و ئەگەر هەبێت بەرکار دیاری بکە. دواتر بپشکنە ئایا کردار تێپەڕە یان ناتێپەڕە و حاڵەتی ناو و جێناوەکان چیە.</p></section><section class="klesson-card"><h2>٢. پێکهاتەی ناوی</h2><p>ناو دەتوانێت لەگەڵ دیارخەر، ژمارە، خاوەندار و هاوەڵناو پێکهاتەیەکی فراوان دروست بکات. لە کورمانجی‌دا هاوەڵناو و خاوەندار زۆرجار بە ئەزافەوە بە ناوە سەرەکییەکە دەبەسترێن.</p></section><section class="klesson-card"><h2>٣. زانیاریی نوێ و جەخت</h2><p>لە گفتوگۆدا هەندێک بەش بۆ جەختکردن یان گونجاندن لەگەڵ زانیاریی پێشوو دەکرێت بگوازرێنەوە. بۆیە نابێت هەر جیاوازییەکی ڕیزبەندی بە هەڵەی ڕێزمانی دابنرێت؛ سیاق و شێوازی بەکارهێنان پەیویستن.</p></section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note">ڕیزبەندیی بکەر–بەرکار–کردار وەک ڕێڕەوی بنەڕەتی فێر دەکرێت، نەک وەک یاسایەکی بێ‌استثنا. جیاوازییە زمانیەکان و جەخت لەبەرچاو بگرە.</p></section>
<section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>لە شیکردنەوەی ڕستەدا چ ئەرکەکان دیاری دەکرێن؟</li><li>ئەزافە لە پێکهاتەی ناوی‌دا چ ڕۆڵێک هەیە؟</li><li>بۆچی ڕیزبەندیی وشەکان هەمیشە بێ‌استثنا نیە؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. Berlin: De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI: 10.1515/9783110421682-004</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">وەشانی سەرچاوە</a>.</li></ul><p class="klesson-note">نمونە و یاساکان لە چوارچێوەی کورمانجیی ستاندارددا پێشکەش کراون؛ بۆ جیاوازیی شێوەزار و فۆڕمی تایبەت، دەبێت سەرچاوە و سیاق دیاری بکرێن.</p></section>',now()),
  ('kurmanji-course-2-lesson-12.html','kurmanji-course-2','پێداچوونەوە و تاقیکردنەوەی کۆتایی','<section class="klesson-card"><h2>١. پێداچوونەوەی مۆرفۆلۆجی</h2><p>مۆرفیم و ڕەگ بناسە؛ پێشگر و پاشگر لە بەراوردی فۆڕمەکاندا دیاری بکە. پاشگری -ek لە ناوی تاکدا زۆرجار نادیاری دەردەخات، بەڵام سیاق و حاڵەت لە شیکردنەوەدا گرنگن.</p></section><section class="klesson-card"><h2>٢. پێداچوونەوەی پێکهاتەی ناوی</h2><p>ڕەگەز و ژمارەی ناو لەگەڵ ئەزافە و هاوەڵناو پشکنە. لە پێکهاتەی خاوەنداریدا، ناوی سەرەکی و خاوەندار لە یەکتر جیا بکەوە.</p></section><section class="klesson-card"><h2>٣. پێداچوونەوەی کردار و ڕستە</h2><p>فۆڕمی جێناوی ڕاستەوخۆ و ناڕاستەوخۆ جیا بکەوە؛ کات و تێپەڕی/ناتێپەڕی کردار دیاری بکە. نەفی و پرسیار لە ڕستەی تەواودا بپشکنە و ڕیزبەندی وشەکان بەبێ لەبەرچاوگرتنی سیاق هەڵنەسەنگێنە.</p></section><section class="klesson-card"><h2>٤. ڕاهێنانی کۆتایی</h2><p>ڕستەیەکی کورمانجی هەڵبژێرە و (١) ناو و کردارەکان دیاری بکە، (٢) فۆڕمی جێناو و حاڵەت بنووسە، (٣) ئەزافە و پاشگرەکان شیکەرەوە، (٤) کات و نەفی/پرسیار پشکنە، (٥) هەر بڕیارێک بە سەرچاوە و سیاق پشتگیری بکە.</p></section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note">ئەم پێداچوونەوەیە تاقیکردنەوەی زانیارییە، نەک جێگرەوەی ڕاهێنانی لەگەڵ دەقی سەرچاوە. هەر نمونەیەکی نوێ پێش بەکارهێنانی فێرکاری دەبێت بە سەرچاوەی ڕێزمانی بەراورد بکرێت.</p></section>
<section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>پاشگری -ek، ئەزافە و حاڵەت چ جیاوازییەکیان هەیە؟</li><li>بۆچی فۆڕمی جێناو بە کات و جۆری ڕستە پەیوەستە؟</li><li>لە شیکردنەوەی زانستیی ڕستەدا چۆن سەرچاوە بەکار دەهێنیت؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. Berlin: De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI: 10.1515/9783110421682-004</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">وەشانی سەرچاوە</a>.</li></ul><p class="klesson-note">نمونە و یاساکان لە چوارچێوەی کورمانجیی ستاندارددا پێشکەش کراون؛ بۆ جیاوازیی شێوەزار و فۆڕمی تایبەت، دەبێت سەرچاوە و سیاق دیاری بکرێن.</p></section>',now())
